package com.vanigam.clothing;
import android.app.*;import android.content.*;import android.content.pm.*;import android.net.Uri;import android.os.Build;import android.provider.Settings;import org.json.*;import java.io.*;import java.net.*;import java.security.*;import java.util.*;
public final class Updater {
 // Public release repository only; no GitHub tokens are stored in the app.
 public static final String DEFAULT_REPO="Sivasakthi7903/Vanigam";
 static final long MAX_APK=100L*1024*1024;
 static String repo(Context c){return c.getSharedPreferences("updates",0).getString("repo",DEFAULT_REPO);}
 static void configure(Context c,String repo)throws Exception{c.getSharedPreferences("updates",0).edit().putString("repo",UpdatePolicy.repo(repo)).apply();}
 static String version(Context c)throws Exception{return c.getPackageManager().getPackageInfo(c.getPackageName(),0).versionName;}
 static long code(PackageInfo p){return Build.VERSION.SDK_INT>=28?p.getLongVersionCode():p.versionCode;}
 static HttpURLConnection open(String url)throws Exception{for(int i=0;i<6;i++){if(!UpdatePolicy.trusted(url))throw new Exception("Untrusted update download URL.");HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();c.setConnectTimeout(15000);c.setReadTimeout(30000);c.setInstanceFollowRedirects(false);c.setRequestProperty("User-Agent","Vanigam-Clothing-Updater");int status=c.getResponseCode();if(status>=300&&status<400){String location=c.getHeaderField("Location");c.disconnect();if(location==null)throw new Exception("Missing download location.");url=new URL(new URL(url),location).toString();continue;}if(status!=200){c.disconnect();throw new Exception(status==404?"Public repository / published release not found.":status==403?"GitHub rate limit or access denied. Try again later.":"GitHub returned HTTP "+status);}return c;}throw new Exception("Too many download redirects.");}
 static byte[] bytes(String url,int limit)throws Exception{HttpURLConnection c=open(url);try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(out.size()+n>limit)throw new Exception("Response too large.");out.write(b,0,n);}return out.toByteArray();}finally{c.disconnect();}}
 public static void check(MainActivity a){a.worker.execute(()->{try{a.requireAdmin();String repo=repo(a);if(repo.isEmpty())throw new Exception("Save the GitHub repository in Settings > App updates first.");repo=UpdatePolicy.repo(repo);JSONObject release=new JSONObject(new String(bytes("https://api.github.com/repos/"+repo+"/releases/latest",1024*1024),"UTF-8"));if(release.optBoolean("draft")||release.optBoolean("prerelease"))throw new Exception("No stable release available.");String tag=release.getString("tag_name");if(UpdatePolicy.compare(tag,version(a))<=0){a.event("You already have the latest version ("+version(a)+").");return;}JSONArray assets=release.getJSONArray("assets");JSONObject selected=null;for(int i=0;i<assets.length();i++){JSONObject item=assets.getJSONObject(i);String name=item.getString("name");if(name.startsWith("Vanigam-Clothing-")&&name.endsWith(".apk")){if(selected!=null)throw new Exception("Release has multiple APKs. Publish one Vanigam-Clothing APK.");selected=item;}}if(selected==null)throw new Exception("No Vanigam-Clothing APK attached to this release.");if(selected.getLong("size")<=0||selected.getLong("size")>MAX_APK)throw new Exception("Invalid update size.");JSONObject asset=selected;String expectedRepo=repo;String url=asset.getString("browser_download_url");if(!url.startsWith("https://github.com/"+expectedRepo+"/releases/download/"))throw new Exception("Update asset does not belong to this repository.");a.runOnUiThread(()->new AlertDialog.Builder(a).setTitle("Update available: "+tag).setMessage("Download from GitHub and install? Existing store data will remain. Android will ask for installation confirmation.").setNegativeButton("Later",null).setPositiveButton("Download",(d,w)->download(a,asset)).show());}catch(Exception e){a.event(e.getMessage());}});}
 static void download(MainActivity a,JSONObject asset){a.event("Downloading update…");a.worker.execute(()->{File tmp=new File(a.getCacheDir(),"update-download.tmp");try{a.requireAdmin();HttpURLConnection c=open(asset.getString("browser_download_url"));long size=0;MessageDigest hash=MessageDigest.getInstance("SHA-256");try(InputStream in=c.getInputStream();OutputStream out=new FileOutputStream(tmp)){byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1){size+=n;if(size>MAX_APK)throw new Exception("Update is too large.");hash.update(b,0,n);out.write(b,0,n);}}finally{c.disconnect();}if(size!=asset.getLong("size"))throw new Exception("Incomplete download. Try again.");String expected=asset.optString("digest","");if(expected.startsWith("sha256:")){StringBuilder actual=new StringBuilder();for(byte b:hash.digest())actual.append(String.format(Locale.US,"%02x",b));if(!expected.substring(7).equalsIgnoreCase(actual.toString()))throw new Exception("Update checksum mismatch.");}verify(a,tmp);File dest=UpdateProvider.file(a);if(dest.exists()&&!dest.delete())throw new Exception("Cannot replace previous update.");if(!tmp.renameTo(dest))throw new Exception("Cannot save downloaded update.");a.runOnUiThread(()->install(a));}catch(Exception e){tmp.delete();a.event(e.getMessage());}});}
 static void verify(Context c,File file)throws Exception{PackageManager pm=c.getPackageManager();int flags=Build.VERSION.SDK_INT>=28?PackageManager.GET_SIGNING_CERTIFICATES:PackageManager.GET_SIGNATURES;PackageInfo current=pm.getPackageInfo(c.getPackageName(),flags),next=pm.getPackageArchiveInfo(file.getAbsolutePath(),flags);if(next==null||!c.getPackageName().equals(next.packageName)||code(next)<=code(current))throw new Exception("APK is not a newer Vanigam Clothing update.");if(!signers(current).equals(signers(next)))throw new Exception("Update rejected: signing certificate does not match this installed app.");}
 static Set<String> signers(PackageInfo p)throws Exception{android.content.pm.Signature[] signatures=Build.VERSION.SDK_INT>=28?p.signingInfo.getApkContentsSigners():p.signatures;Set<String> set=new HashSet<>();if(signatures==null||signatures.length==0)throw new Exception("Missing APK signing certificate.");for(android.content.pm.Signature s:signatures)set.add(java.util.Base64.getEncoder().encodeToString(MessageDigest.getInstance("SHA-256").digest(s.toByteArray())));return set;}
 static void install(MainActivity a){try{a.requireAdmin();File apk=UpdateProvider.file(a);if(!apk.exists())throw new Exception("Check for updates to download the latest APK first.");verify(a,apk);if(!a.getPackageManager().canRequestPackageInstalls()){a.startActivity(new Intent(Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES,Uri.parse("package:"+a.getPackageName())));a.event("Allow this app to install updates, return here, then tap Install downloaded update.");return;}Uri uri=Uri.parse("content://"+a.getPackageName()+".updates/update.apk");Intent install=new Intent(Intent.ACTION_VIEW).setDataAndType(uri,"application/vnd.android.package-archive").addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);a.startActivity(install);}catch(Exception e){a.event(e.getMessage());}}
}
